const items = $input.all();
const cleaned = [];
const errors = [];

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phoneRegex = /^[\+]?[0-9\s\-\(\)]{7,15}$/;
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

for (let i = 0; i < items.length; i++) {
  const row = { ...items[i].json };
  const rowErrors = [];
  const rowNum = i + 2; // +2 for header and 0-index

  // Email validation
  if (row.email) {
    row.email = row.email.trim().toLowerCase();
    if (!emailRegex.test(row.email)) {
      rowErrors.push({ row: rowNum, field: 'email', value: row.email, issue: 'Invalid email format' });
    }
  }

  // Phone validation
  if (row.phone) {
    row.phone = row.phone.replace(/[^0-9+\-\s()]/g, '').trim();
    if (!phoneRegex.test(row.phone)) {
      rowErrors.push({ row: rowNum, field: 'phone', value: row.phone, issue: 'Invalid phone format' });
    }
  }

  // Date validation
  if (row.date) {
    const d = row.date.trim();
    if (!dateRegex.test(d) || isNaN(new Date(d).getTime())) {
      rowErrors.push({ row: rowNum, field: 'date', value: d, issue: 'Invalid date format (expected YYYY-MM-DD)' });
    }
  }

  // Trim all string fields
  for (const key of Object.keys(row)) {
    if (typeof row[key] === 'string') row[key] = row[key].trim();
  }

  cleaned.push(row);
  errors.push(...rowErrors);
}

return [{ json: { cleaned, errors, totalRows: items.length, errorCount: errors.length, cleanedAt: new Date().toISOString() } }];

